def test_invalid_domains(self):
    invalid = [
        'python..org',
        # FIXME: '****.foo.com', current validator says this is valid :shrug:
        'invalid-.com'
    ]
    for domain in invalid:
        form = DomainForm(
            {'domain': domain},
            project=self.project,
        )
        self.assertFalse(form.is_valid(), domain)
